<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import AppSelect from '../shared/AppSelect.vue'
import type { ExplorerObject, ExplorerLink } from './explorerTypes'
const props=defineProps<{objects:ExplorerObject[];allObjects:ExplorerObject[];links:ExplorerLink[];selectedId?:string}>()
const emit=defineEmits<{select:[id:string]}>()
const mode=ref('table'),page=ref(1),pageSize=ref('20'),sortKey=ref('name'),ascending=ref(true),columns=ref<string[]>([]),compareIds=ref<string[]>([]),showCompare=ref(false)
const propertyKeys=computed(()=>[...new Set(props.objects.flatMap(o=>Object.keys(o.properties)))])
function label(key:string){return props.allObjects.find(o=>o.propertyLabels[key])?.propertyLabels[key]||key}
function display(value:unknown):string {if(value===null||value===undefined||value==='')return '—';return typeof value==='object'?JSON.stringify(value):String(value)}
function value(o:ExplorerObject,key:string):unknown{return key==='name'?o.name:key==='typeName'?o.typeName:key==='id'?o.id:o.properties[key]}
const sorted=computed(()=>[...props.objects].sort((a,b)=>{const av=value(a,sortKey.value),bv=value(b,sortKey.value);const order=typeof av==='number'&&typeof bv==='number'?av-bv:display(av).localeCompare(display(bv),'zh-CN',{numeric:true});return ascending.value?order:-order}))
const pages=computed(()=>Math.max(1,Math.ceil(sorted.value.length/Number(pageSize.value))))
const paged=computed(()=>sorted.value.slice((page.value-1)*Number(pageSize.value),page.value*Number(pageSize.value)))
const selected=computed(()=>props.allObjects.find(o=>o.id===props.selectedId))
const related=computed(()=>props.links.filter(l=>l.source===props.selectedId||l.target===props.selectedId).map(l=>({link:l,other:props.allObjects.find(o=>o.id===(l.source===props.selectedId?l.target:l.source)),out:l.source===props.selectedId})))
const comparison=computed(()=>compareIds.value.map(id=>props.allObjects.find(o=>o.id===id)).filter((o):o is ExplorerObject=>!!o))
const compareKeys=computed(()=>[...new Set(comparison.value.flatMap(o=>Object.keys(o.properties)))])
watch(propertyKeys,keys=>{columns.value=columns.value.filter(k=>keys.includes(k));if(!columns.value.length)columns.value=keys.slice(0,4)},{immediate:true})
watch(()=>props.objects,()=>{page.value=1})
watch(pageSize,()=>{page.value=1})
watch(pages,n=>{page.value=Math.min(page.value,n)})
watch(()=>props.allObjects,objects=>{compareIds.value=compareIds.value.filter(id=>objects.some(o=>o.id===id));if(compareIds.value.length<2)showCompare.value=false})
function sort(key:string){if(sortKey.value===key)ascending.value=!ascending.value;else {sortKey.value=key;ascending.value=true}}
function compare(id:string){if(compareIds.value.includes(id))compareIds.value=compareIds.value.filter(i=>i!==id);else if(compareIds.value.length<4)compareIds.value.push(id);if(compareIds.value.length<2)showCompare.value=false}
function csvCell(v:unknown){let s=v===null||v===undefined?'':typeof v==='object'?JSON.stringify(v):String(v);if(/^[\s\u0000-\u001f]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportCsv(){const keys=['name','typeName','id',...columns.value];const lines=[['对象名称','对象类型','标识',...columns.value.map(label)],...sorted.value.map(o=>keys.map(k=>value(o,k)))];const url=URL.createObjectURL(new Blob(['\ufeff'+lines.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='本体对象数据.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template>
<section class="instance-table">
  <div class="it-toolbar">
    <div class="it-modes" aria-label="对象展示方式"><button :class="{active:mode==='table'}" @click="mode='table'">表格</button><button :class="{active:mode==='cards'}" @click="mode='cards'">卡片</button></div>
    <span class="it-muted">{{ objects.length }} 个对象</span>
    <details class="it-columns"><summary>显示属性（{{ columns.length }}）</summary><div class="it-column-menu"><label v-for="key in propertyKeys" :key="key"><input v-model="columns" type="checkbox" :value="key">{{ label(key) }}</label><span v-if="!propertyKeys.length">暂无属性</span></div></details>
    <button :disabled="comparison.length<2" @click="showCompare=!showCompare">{{ showCompare?'收起对比':'对比所选' }}（{{ comparison.length }}/4）</button>
    <button v-if="comparison.length" @click="compareIds=[];showCompare=false">清空选择</button>
    <button :disabled="!objects.length" @click="exportCsv">导出筛选结果 CSV</button>
  </div>
  <p class="it-hint">勾选 2–4 个对象可逐项对比；点击对象名称查看属性、来源及关联对象。导出包含全部筛选结果与当前显示属性。</p>
  <div v-if="showCompare" class="it-compare"><h3>对象属性对比</h3><div class="it-scroll"><table><thead><tr><th>字段</th><th v-for="o in comparison" :key="o.id">{{ o.name }}<small>{{ o.typeName }}</small></th></tr></thead><tbody><tr><th>标识</th><td v-for="o in comparison" :key="o.id">{{ o.id }}</td></tr><tr v-for="key in compareKeys" :key="key"><th>{{ label(key) }}</th><td v-for="o in comparison" :key="o.id">{{ display(o.properties[key]) }}</td></tr></tbody></table></div></div>
  <div class="it-body" :class="{'has-detail':selected}">
    <div class="it-results">
      <div v-if="!objects.length" class="it-empty">没有符合条件的对象，请调整筛选条件。</div>
      <div v-else-if="mode==='table'" class="it-scroll"><table><thead><tr><th>对比</th><th :aria-sort="sortKey==='name'?(ascending?'ascending':'descending'):'none'"><button @click="sort('name')">对象名称 {{ sortKey==='name'?(ascending?'↑':'↓'):'' }}</button></th><th><button @click="sort('typeName')">对象类型 {{ sortKey==='typeName'?(ascending?'↑':'↓'):'' }}</button></th><th v-for="key in columns" :key="key"><button @click="sort(key)">{{ label(key) }} {{ sortKey===key?(ascending?'↑':'↓'):'' }}</button></th></tr></thead><tbody><tr v-for="o in paged" :key="o.id" :class="{selected:o.id===selectedId}"><td><input type="checkbox" :aria-label="'选择对比 '+o.name" :checked="compareIds.includes(o.id)" :disabled="!compareIds.includes(o.id)&&compareIds.length>=4" @change="compare(o.id)"></td><td><button class="it-link" @click="emit('select',o.id)">{{ o.name }}</button><small>{{ o.id }}</small></td><td>{{ o.typeName }}</td><td v-for="key in columns" :key="key">{{ display(o.properties[key]) }}</td></tr></tbody></table></div>
      <div v-else class="it-cards"><article v-for="o in paged" :key="o.id" :class="{selected:o.id===selectedId}"><div class="it-card-heading"><button class="it-link" @click="emit('select',o.id)">{{ o.name }}</button><input type="checkbox" :aria-label="'选择对比 '+o.name" :checked="compareIds.includes(o.id)" :disabled="!compareIds.includes(o.id)&&compareIds.length>=4" @change="compare(o.id)"></div><p class="it-muted">{{ o.typeName }}</p><small>{{ o.id }}</small><dl><template v-for="key in columns" :key="key"><dt>{{ label(key) }}</dt><dd>{{ display(o.properties[key]) }}</dd></template></dl><button @click="emit('select',o.id)">查看详情</button></article></div>
      <div v-if="objects.length" class="it-pager"><span>第 {{ page }} / {{ pages }} 页</span><button :disabled="page<=1" @click="page--">上一页</button><button :disabled="page>=pages" @click="page++">下一页</button><AppSelect v-model="pageSize" :options="[{value:'10',label:'每页 10 条'},{value:'20',label:'每页 20 条'},{value:'50',label:'每页 50 条'}]" aria-label="每页条数" /></div>
    </div>
    <aside v-if="selected" class="it-detail" aria-label="对象详情"><div class="it-card-heading"><h3>{{ selected.name }}</h3><button @click="emit('select','')">关闭详情</button></div><p>{{ selected.typeName }}</p><small>{{ selected.id }}</small><h4>属性</h4><dl><template v-for="(v,key) in selected.properties" :key="key"><dt>{{ selected.propertyLabels[key]||key }}</dt><dd>{{ display(v) }}</dd></template></dl><p v-if="!Object.keys(selected.properties).length" class="it-muted">暂无属性值</p><h4>数据来源</h4><p class="it-wrap">{{ selected.source||'未提供来源信息' }}</p><h4>关联对象（{{ related.length }}）</h4><ul v-if="related.length"><li v-for="r in related" :key="r.link.id"><span class="it-muted">{{ r.out?'→':'←' }} {{ r.link.name }}</span><button v-if="r.other" class="it-link" @click="emit('select',r.other.id)">{{ r.other.name }}</button><span v-else>{{ r.out?r.link.target:r.link.source }}（当前数据集中不可用）</span></li></ul><p v-else class="it-muted">暂无关联对象</p></aside>
  </div>
</section>
</template>
<style scoped>
.instance-table{color:var(--ink);min-width:0}.it-toolbar,.it-pager,.it-card-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.it-toolbar{padding:12px 0}.it-modes{display:flex;gap:4px}.instance-table button{border:1px solid var(--line);background:var(--paper);border-radius:6px;padding:7px 10px;color:var(--ink-2);cursor:pointer}.instance-table button:hover{background:var(--blue-soft)}.instance-table button:disabled{opacity:.45;cursor:default}.it-modes button.active{background:var(--blue-soft);border-color:#498ae4;color:#1c62bb}.it-muted,.it-hint,small{color:#708198}.it-hint{font-size:12px;margin:0 0 14px}.it-body{display:grid;grid-template-columns:minmax(0,1fr);gap:16px}.it-body.has-detail{grid-template-columns:minmax(0,1fr) minmax(260px,340px)}.it-results{min-width:0}.it-scroll{overflow:auto;border:1px solid var(--line);border-radius:8px;max-height:650px}table{border-collapse:collapse;width:100%;font-size:13px;text-align:left}th,td{padding:11px 13px;border-bottom:1px solid var(--line);vertical-align:top;max-width:360px;overflow-wrap:anywhere}th{background:var(--paper-2);white-space:nowrap}thead th{position:sticky;top:0;z-index:1}th button{border:0!important;background:transparent!important;padding:0!important;font-weight:600}small{display:block;font-size:11px;margin-top:4px;overflow-wrap:anywhere}.selected{background:var(--blue-soft)!important}.instance-table .it-link{border:0;background:transparent;padding:0;color:#236bc7;text-align:left;overflow-wrap:anywhere}.it-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px}.it-cards article,.it-detail,.it-compare{border:1px solid var(--line);background:var(--paper);border-radius:9px;padding:16px}.it-card-heading{justify-content:space-between}.it-card-heading h3{margin:0}.it-card-heading .it-link{font-size:15px;font-weight:600}dl{display:grid;grid-template-columns:minmax(80px,1fr) minmax(80px,1.3fr);gap:10px;font-size:13px}dt{color:#708198;overflow-wrap:anywhere}dd{margin:0;overflow-wrap:anywhere}.it-detail{align-self:start;max-height:750px;overflow:auto}.it-detail h4{margin:22px 0 10px;font-size:13px}.it-detail ul{list-style:none;padding:0;margin:0}.it-detail li{display:grid;gap:6px;padding:10px 0;border-bottom:1px solid var(--paper-3)}.it-pager{justify-content:flex-end;padding:14px 0;font-size:13px}.it-pager :deep(.app-select){max-width:145px}.it-empty{text-align:center;padding:60px 20px;border:1px dashed var(--line-2);border-radius:8px;color:#708198}.it-columns{position:relative}.it-columns summary{cursor:pointer;padding:8px;font-size:13px}.it-column-menu{position:absolute;z-index:5;background:var(--paper);border:1px solid var(--line);box-shadow:0 8px 28px #23405d22;max-height:300px;overflow:auto;min-width:230px;padding:12px;border-radius:8px}.it-column-menu label{display:flex;align-items:center;gap:8px;padding:7px;font-size:13px}.it-compare{margin-bottom:16px}.it-compare h3{margin:0 0 12px;font-size:15px}.it-wrap{overflow-wrap:anywhere}@media(max-width:1050px){.it-body.has-detail{grid-template-columns:minmax(0,1fr)}.it-detail{max-height:none}}input[type=checkbox]{accent-color:#2874d1;width:16px;height:16px}
</style>
